        size: [len, thick, width],
        position: [pos.x, pos.y, pos.z],
        rotation: [euler.x, euler.y, euler.z],
        color: side < 0 ? color1 : color2
      });
    }
  };

  // Stage 1: Upper Warm Walnut & Maple Express Chute
  const pStart = new THREE.Vector3(-0.915, 0.71, -0.324);
  const pMid = new THREE.Vector3(-0.02, 0.36, 0.002);
  const pEnd = new THREE.Vector3(0.73, 0.09, 0.275);

  addVTrough(pStart, pMid, 0.084, 0.014, 0.50, '#7c4724', '#94572f');

  // Stage 2: Lower Brushed Brass & Copper Runout Chute
  addVTrough(new THREE.Vector3(-0.08, 0.36, -0.02), pEnd, 0.078, 0.014, 0.48, '#c88736', '#dfa048');

  // Cup Pavilion Backstop & Angled Guide Wings (Unified Dark Slate Steel)
  add.box({
    size: [0.016, 0.16, 0.15],
    position: [0.855, 0.11, 0.32],
    rotation: [0, yaw, 0.1],
    color: '#2c3d4f'
  });
  add.box({
    size: [0.15, 0.13, 0.014],
    position: [0.78, 0.095, 0.375],
    rotation: [0, yaw - 0.2, 0],
    color: '#2c3d4f'
  });
  add.box({
    size: [0.15, 0.13, 0.014],
    position: [0.81, 0.095, 0.225],
    rotation: [0, yaw + 0.2, 0],
    color: '#2c3d4f'
  });

  // Upper Launch Hopper Back Guard
  add.box({
    size: [0.014, 0.10, 0.08],
    position: [-0.935, 0.75, -0.33],
    rotation: [0, yaw, 0],
    color: '#2c3d4f'
  });

  // Mover 1: Precision Cup Keeper Lid (0.125m x 0.125m so it sits cleanly inside the cup rim and side wings without clipping!)
  add.mover({
    size: [0.125, 0.016, 0.125],
    color: '#d4af37',
    path: (t, marble) => {
      const mx = marble.position[0], my = marble.position[1], mz = marble.position[2];
      const dCup = Math.hypot(mx - 0.8, mz - 0.3);
      if (dCup < 0.065 && my < 0.055) {
        return { position: [0.8, 0.068, 0.3], rotation: [0, yaw, 0] };
      }
      return { position: [0.62, 0.24, 0.23], rotation: [0, yaw, 0] };
    }
  });

  // Mover 2: Mid-Track Kinetic Escapement Gate & Secondary Cup Seal (0.095m x 0.095m, aligned cleanly!)
  add.mover({
    size: [0.095, 0.016, 0.095],
    color: '#b87333',
    path: (t, marble) => {
      const mx = marble.position[0], my = marble.position[1], mz = marble.position[2];
      const dCup = Math.hypot(mx - 0.8, mz - 0.3);
      if (dCup < 0.065 && my < 0.055) {
        return { position: [0.8, 0.084, 0.3], rotation: [0, yaw, 0] };
      }
      return { position: [-0.05, 0.47, -0.01], rotation: [0, yaw, -0.36] };
    }
  });

  // ==================== DECOR: MULTI-STAGE ARCHITECTURAL DESK TOY & OFFICE SCENE ====================
  const g = new THREE.Group();
  const shadow = (m) => { m.castShadow = true; m.receiveShadow = true; return m; };

  const matWoodDark = new THREE.MeshStandardMaterial({ color: '#5c3a21', roughness: 0.55, metalness: 0.05 });
  const matWoodLight = new THREE.MeshStandardMaterial({ color: '#c89d66', roughness: 0.45, metalness: 0.05 });
  const matBrass = new THREE.MeshStandardMaterial({ color: '#d4af37', roughness: 0.25, metalness: 0.85 });
  const matCopper = new THREE.MeshStandardMaterial({ color: '#b87333', roughness: 0.3, metalness: 0.8 });
  const matSteel = new THREE.MeshStandardMaterial({ color: '#2c3d4f', roughness: 0.35, metalness: 0.7 });
  const matFelt = new THREE.MeshStandardMaterial({ color: '#2b3137', roughness: 0.9, metalness: 0.0 });
  const matCream = new THREE.MeshStandardMaterial({ color: '#f5f0e6', roughness: 0.6, metalness: 0.05 });
  const matGreen = new THREE.MeshStandardMaterial({ color: '#2d5a3c', roughness: 0.4, metalness: 0.1 });
  const matTerracotta = new THREE.MeshStandardMaterial({ color: '#b35437', roughness: 0.7, metalness: 0.05 });
  const matCeramic = new THREE.MeshStandardMaterial({ color: '#e8e2d5', roughness: 0.3, metalness: 0.05 });

  const makeRod = (p1, p2, r, mat) => {
    const v = new THREE.Vector3().subVectors(p2, p1);
    const len = v.length();
    const mid = new THREE.Vector3().addVectors(p1, p2).multiplyScalar(0.5);
    const mesh = shadow(new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 16), mat));
    mesh.position.copy(mid);
    mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), v.normalize());
    return mesh;
  };

  // 1. Table legs under the desk (4 tapered mid-century wooden legs with brass ferrules)
  for (const [lx, lz] of [[-0.9, -0.42], [0.9, -0.42], [-0.9, 0.42], [0.9, 0.42]]) {
    const leg = shadow(new THREE.Mesh(new THREE.CylinderGeometry(0.032, 0.018, 0.72, 16), matWoodDark));
    leg.position.set(lx, -0.39, lz);
    g.add(leg);
    const ferrule = shadow(new THREE.Mesh(new THREE.CylinderGeometry(0.021, 0.018, 0.12, 16), matBrass));
    ferrule.position.set(lx, -0.69, lz);
    g.add(ferrule);
  }

  // 2. Sculpted wooden base plinth strictly inside the desk footprint!
  const baseLen = 1.88;
  const basePlinth = shadow(new THREE.Mesh(new THREE.BoxGeometry(baseLen, 0.014, 0.21), matWoodDark));
  basePlinth.position.set(-0.025, 0.007, 0.0);
  basePlinth.rotation.y = yaw;
  g.add(basePlinth);

  const baseInlay = shadow(new THREE.Mesh(new THREE.BoxGeometry(baseLen - 0.04, 0.016, 0.17), matWoodLight));
  baseInlay.position.set(-0.025, 0.008, 0.0);
  baseInlay.rotation.y = yaw;
  g.add(baseInlay);

  // 3. Support Bents (5 graduated architectural support frames with cylindrical cross-rods & spherical brass joints!)
  const trackLine = (s) => new THREE.Vector3().lerpVectors(pStart, pEnd, s);
  const zPerp = new THREE.Vector3(-Math.sin(yaw), 0, Math.cos(yaw));
  const stations = [0.035, 0.22, 0.40, 0.57, 0.76];

  for (let i = 0; i < stations.length; i++) {
    const s = stations[i];
    const pt = trackLine(s);
    const yCross = pt.y - 0.038;
    const pLeftTop = pt.clone().addScaledVector(zPerp, -0.058).setY(yCross);
    const pRightTop = pt.clone().addScaledVector(zPerp, 0.058).setY(yCross);
    const pLeftBot = pLeftTop.clone().setY(0.016);
    const pRightBot = pRightTop.clone().setY(0.016);

    // Cylindrical crossbar between the two pillars + center V-cradle saddle
    g.add(makeRod(pLeftTop, pRightTop, 0.007, matBrass));
    const saddle = shadow(new THREE.Mesh(new THREE.CylinderGeometry(0.013, 0.010, 0.022, 16), matWoodLight));
    saddle.position.set(pt.x, yCross + 0.008, pt.z);
    g.add(saddle);

    for (const [pTop, pBot] of [[pLeftTop, pLeftBot], [pRightTop, pRightBot]]) {
      // Spherical brass joint where the crossbar meets the vertical pillar
      const joint = shadow(new THREE.Mesh(new THREE.SphereGeometry(0.013, 16, 16), matBrass));
      joint.position.copy(pTop);
      g.add(joint);

      // Vertical pillar
      g.add(makeRod(pBot, pTop, 0.0085, i % 2 === 0 ? matBrass : matSteel));

      // Stepped wooden & brass base foot
      const foot = shadow(new THREE.Mesh(new THREE.CylinderGeometry(0.016, 0.021, 0.018, 16), matWoodDark));
      foot.position.copy(pBot);
      g.add(foot);
    }

